CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE connection_state AS ENUM ('requested','connected','rejected','expired','blocked','unmatched');
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), username text NOT NULL, username_norm text UNIQUE NOT NULL, adult_verified_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE profiles (user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, display_name text NOT NULL, bio text NOT NULL DEFAULT '', locale text NOT NULL DEFAULT 'en-IN', visibility text NOT NULL DEFAULT 'pilot');
CREATE TABLE devices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, platform text NOT NULL CHECK(platform IN ('ios','android')), push_token_ciphertext bytea, last_seen_at timestamptz);
CREATE TABLE consents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, purpose text NOT NULL, policy_version text NOT NULL, granted boolean NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE music_selections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, canonical_track_id text NOT NULL, title text NOT NULL, artist text NOT NULL, source text NOT NULL, selected_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL);
CREATE TABLE presence_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, device_id uuid NOT NULL REFERENCES devices(id), state text NOT NULL, started_at timestamptz NOT NULL, expires_at timestamptz NOT NULL, ended_at timestamptz);
CREATE INDEX presence_active_idx ON presence_sessions(expires_at) WHERE ended_at IS NULL;
CREATE TABLE proximity_encounters (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), observer_id uuid NOT NULL REFERENCES users(id), observed_user_id uuid NOT NULL REFERENCES users(id), bucket text NOT NULL, protocol_version smallint NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, CHECK(observer_id<>observed_user_id));
CREATE TABLE match_candidates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_a uuid NOT NULL REFERENCES users(id), user_b uuid NOT NULL REFERENCES users(id), score smallint NOT NULL CHECK(score BETWEEN 0 AND 100), category text NOT NULL, explanation text NOT NULL, algorithm_version text NOT NULL, status text NOT NULL DEFAULT 'candidate', expires_at timestamptz NOT NULL);
CREATE INDEX candidate_a_idx ON match_candidates(user_a,status,expires_at); CREATE INDEX candidate_b_idx ON match_candidates(user_b,status,expires_at);
CREATE TABLE connections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_a uuid NOT NULL REFERENCES users(id), user_b uuid NOT NULL REFERENCES users(id), requested_by uuid NOT NULL REFERENCES users(id), state connection_state NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(user_a<>user_b));
CREATE TABLE conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), connection_id uuid UNIQUE NOT NULL REFERENCES connections(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, sender_id uuid NOT NULL REFERENCES users(id), body text NOT NULL CHECK(length(body) BETWEEN 1 AND 1000), created_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE INDEX messages_cursor_idx ON messages(conversation_id,created_at,id);
CREATE TABLE blocks (blocker_id uuid NOT NULL REFERENCES users(id), blocked_id uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(blocker_id,blocked_id), CHECK(blocker_id<>blocked_id));
CREATE TABLE reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reporter_id uuid NOT NULL REFERENCES users(id), target_id uuid NOT NULL REFERENCES users(id), message_id uuid REFERENCES messages(id), reason text NOT NULL, status text NOT NULL DEFAULT 'open', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX reports_queue_idx ON reports(status,created_at);
CREATE TABLE audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid, action text NOT NULL, target_type text, target_id uuid, reason text, created_at timestamptz NOT NULL DEFAULT now());
